58	// What the plug-in did, as observed. -1 came with a wrong code and with the
59	// right one on a slow network, so it is not read as either.
60	std::string connection_failure_text(const Printers::ConnectionEvent& answer, std::chrono::steady_clock::time_point asked)
61	{
62	    if (answer.kind == Printers::ConnectionEvent::Kind::Lost)
63	        return "The connection to the printer was lost before it answered.";
64	    if (answer.code == "5")
65	        return "The printer refused the access code. The app has dropped the code it had saved for this printer; the person "
66	               "gives the code shown on the printer's screen again to try again.";
67	    const auto took = std::chrono::duration_cast<std::chrono::seconds>(answer.at - asked).count();
68	    return "Bambu's network plug-in reported code " + answer.code + " " + std::to_string(took) +
69	           " seconds after being asked to connect, which does not say why.";
70	}
