72	// A host's answer as one bounded line: a response body can be a page.
73	std::string one_line(std::string text)
74	{
75	    for (char& c : text)
76	        if (c == '\r' || c == '\n' || c == '\t')
77	            c = ' ';
78	    std::string out;
79	    for (char c : text)
80	        if (c != ' ' || (!out.empty() && out.back() != ' '))
81	            out += c;
82	    while (!out.empty() && out.back() == ' ')
83	        out.pop_back();
84	    constexpr std::size_t kLimit = 240;
85	    if (out.size() > kLimit)
86	        out = out.substr(0, kLimit) + "...";
87	    return out;
88	}
