115	SetupOptions OrcaPrinterBackend::setup_options(const std::string& catalog_id, double nozzle) const
116	{
117	    // The catalogue and the options read the same files, so a model and size
118	    // the catalogue offered has a machine profile there.
119	    for (const PrinterCandidate& candidate : m_catalog.candidates())
120	        if (candidate.vendor_id + "/" + candidate.model_id == catalog_id && nozzle_of(candidate.variant) == nozzle) {
121	            SetupOptions options = load_setup_options(m_profiles_directory, candidate.vendor_id, candidate.preset_name, m_own_filaments);
122	            options.catalog_id   = catalog_id;
123	            options.nozzle       = nozzle;
124	            return options;
125	        }
126	    throw std::logic_error("The printer form asked about a printer the catalogue does not offer: " + catalog_id);
