143	std::vector<SavedPrinter> OrcaPrinterBackend::saved_printers() const
144	{
145	    const std::vector<DiscoveredPrinter> network = discover_printers(/*include_unreachable=*/true);
146	    const PresetBundle*                  presets = wxGetApp().preset_bundle;
147	
148	    std::vector<SavedPrinter> printers;
149	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
150	        SavedPrinter saved;
151	        saved.name      = named.name;
152	        saved.device_id = named.device_id;
153	        saved.nozzle    = named.nozzle;
154	
155	        if (const CatalogPrinter* model = model_of(named.name)) {
156	            saved.model     = model->display_name();
157	            saved.model_id  = model->model_id;
158	            saved.vendor_id = model->vendor_id;
159	            saved.picture   = model->picture;
160	            saved.nozzles   = model->nozzles;
161	            saved.plate     = model->default_plate;
162	        }
163	        if (presets != nullptr) {
164	            if (const Preset* preset = presets->printers.find_preset(named.name, false)) {
165	                const std::string plate = preset->config.opt_string("default_bed_type");
166	                if (!plate.empty())
167	                    saved.plate = plate;
168	            }
169	        }
170	
171	        // What the machine says beats what the profile assumed.
172	        const auto found = std::find_if(network.begin(), network.end(),
173	                                        [&saved](const DiscoveredPrinter& device) { return device.stable_id == saved.device_id; });
174	        // A Moonraker host that answered lately is connected, and says what
175	        // its multi-filament unit holds -- nothing, when it has none.
176	        const auto host = Printers::host_status(named.name);
177	        const bool host_answered = host && host->link == Printers::HostLink::Reachable;
178	        if (host_answered)
179	            saved.connected = true;
180	        if (found != network.end() && !saved.device_id.empty()) {
181	            saved.connected = found->connected;
182	            saved.activity  = found->activity == PrinterActivity::Printing ? "printing" :
183	                              found->activity == PrinterActivity::Idle     ? "idle" :
184	                                                                            "offline";
185	            saved.ams       = found->ams_name;
186	            for (const DiscoveredPrinter::Spool& spool : found->spools)
187	                saved.spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
188	        } else if (host_answered && host->loaded) {
189	            // The unit names a material, not a product.
190	            for (const Printers::HostLane& lane : *host->loaded)
191	                saved.spools.push_back(PrinterSpool{lane.material, lane.material, lane.colour});
192	        }
193	        // Not connected, or never was: nothing is known to be loaded, and
194	        // nothing is claimed.
195	        printers.push_back(std::move(saved));
196	    }
197	    return printers;
198	}
