200	SavedPrinter OrcaPrinterBackend::stock_printer(const std::string& name) const
201	{
202	    SavedPrinter stock;
203	    const PresetBundle* presets = wxGetApp().preset_bundle;
204	    const Preset*       preset  = presets != nullptr ? Printers::preset_by_name(*presets, Preset::TYPE_PRINTER, name) : nullptr;
205	    if (preset == nullptr || preset->name != name || !preset->is_system)
206	        return stock;
207	    stock.name      = preset->name;
208	    stock.stock     = true;
209	    stock.copy_name = Printers::copy_name(name, [presets](const std::string& candidate) {
210	        return std::any_of(presets->printers.begin(), presets->printers.end(),
211	                           [&candidate](const Preset& preset) { return boost::iequals(preset.name, candidate); });
212	    });
213	    if (const auto* nozzle = preset->config.option<ConfigOptionFloats>("nozzle_diameter"); nozzle && !nozzle->values.empty())
214	        stock.nozzle = nozzle->values.front();
215	    if (const CatalogPrinter* model = model_of(name)) {
216	        stock.model     = model->display_name();
217	        stock.model_id  = model->model_id;
218	        stock.vendor_id = model->vendor_id;
219	        stock.picture   = model->picture;
220	        stock.nozzles   = model->nozzles;
221	        stock.plate     = model->default_plate;
222	    }
223	    return stock;
224	}
