234	std::string OrcaPrinterBackend::start_with_filament(const std::string& printer, const std::string& filament, bool copy,
235	                                                    std::string& used)
236	{
237	    PresetBundle* presets = wxGetApp().preset_bundle;
238	    if (presets->printers.get_selected_preset_name() != printer)
239	        throw std::logic_error("A filament was chosen for " + printer + ", which is not the selected printer");
240	    const Preset* source  = presets->filaments.find_preset(filament, false);
241	    if (source == nullptr || source->name != filament)
242	        return "The filament " + filament + " is no longer there.";
243	    std::string chosen = filament;
244	    if (copy) {
245	        // OrcaSlicer's own "Add preset for new printer"
246	        // (CreatePresetForPrinterDialog): a copy named "<name> @<printer>",
247	        // made for that printer alone, so a printer change keeps it.
248	        const std::string name = source->alias.empty() ? source->name : source->alias;
249	        chosen                 = name + " @" + printer;
250	        if (const Preset* existing = presets->filaments.find_preset(chosen, false); existing == nullptr || existing->name != chosen) {
251	            const auto first = [source](const char* key) {
252	                const auto* values = source->config.option<ConfigOptionStrings>(key);
253	                return values != nullptr && !values->values.empty() ? values->values.front() : std::string();
254	            };
255	            DynamicConfig made_for;
256	            made_for.set_key_value("filament_vendor", new ConfigOptionStrings({first("filament_vendor")}));
257	            made_for.set_key_value("compatible_printers", new ConfigOptionStrings({printer}));
258	            made_for.set_key_value("filament_type", new ConfigOptionStrings({first("filament_type")}));
259	            std::vector<std::string> failures;
260	            if (!presets->filaments.clone_presets_for_filament(source, failures, name, source->filament_id, made_for, printer))
261	                return "A copy of " + name + " for " + printer + " could not be saved" + (failures.empty() ? "." : ": a preset named " + failures.front() + " already exists.");
262	            if (wxGetApp().mainframe)
263	                wxGetApp().mainframe->update_side_preset_ui();
264	        }
265	    }
266	    if (!SetupCommands::select_filament_preset(m_plater, 0, chosen))
267	        return "The filament " + chosen + " could not be put in slot 1.";
268	    used = chosen;
269	    return {};
270	}
