272	std::string OrcaPrinterBackend::create_filament_preset(const std::string& printer)
273	{
274	    PresetBundle*         presets = wxGetApp().preset_bundle;
275	    if (presets->printers.get_selected_preset_name() != printer)
276	        throw std::logic_error("A filament preset was to be made for " + printer + ", which is not the selected printer");
277	    std::set<std::string> before;
278	    for (const Preset& preset : presets->filaments)
279	        if (preset.is_user())
280	            before.insert(preset.name);
281	    // OrcaSlicer's own handler, as its setup guide reaches it: its Create
282	    // filament window, and its note when a preset was made.
283	    SimpleEvent create(EVT_CREATE_FILAMENT);
284	    m_plater.ProcessWindowEvent(create);
285	    const PresetWithVendorProfile selected = presets->printers.get_edited_preset_with_vendor_profile();
286	    for (const Preset& preset : presets->filaments)
287	        if (preset.is_user() && before.count(preset.name) == 0 &&
288	            is_compatible_with_printer(presets->filaments.get_preset_with_vendor_profile(preset), selected)) {
289	            const std::string name = preset.name;
290	            if (!SetupCommands::select_filament_preset(m_plater, 0, name))
291	                return {};
292	            return name;
293	        }
294	    return {};
