297	std::string OrcaPrinterBackend::add_printer(const AddPrinterRequest& request, SavedPrinter& added)
298	{
299	    // Installing and selecting the printer preset marks the open project
300	    // dirty the same way any preset switch does (Tab::select_preset ->
301	    // on_presets_changed -> update_project_dirty_from_presets), even though
302	    // nothing about the project itself changed. Only re-baseline a project
303	    // that was clean before this call, the same way Plater's own new-project
304	    // and load-project paths already do -- a real pending edit must stay
305	    // visible. And only a project with nothing saved to disk yet: for one
306	    // loaded from a file, this switch is now that project's own printer,
307	    // and re-baselining it would mean closing the project never prompts to
308	    // save that -- a real edit, made to look like nothing happened. F9 on
309	    // printer-panel-review-fixes-handoff.md.
310	    const bool was_clean       = !m_plater.is_project_dirty();
311	    const bool no_project_file = m_plater.get_project_filename().IsEmpty();
312	
313	    std::string error;
314	    if (!SetupCommands::install_and_select_printer(m_plater, request.vendor_id, request.model_id, request.variant,
315	                                                  request.material, error))
316	        return error.empty() ? std::string("This printer could not be installed.") : error;
317	
318	    if (was_clean && no_project_file) {
319	        m_plater.reset_project_dirty_initial_presets();
320	        m_plater.update_project_dirty_from_presets();
321	    }
322	
323	    const std::string name =
324	        Printers::add_named_printer(m_plater, request.name.empty() ? request.model_id : request.name, request.device_id);
325	    // With the new printer selected, the plate goes through the sidebar's
326	    // own selection, which records it as this printer's plate
327	    // (app_config printer_settings), as a pick in the sidebar would.
328	    if (request.plate && !SetupCommands::select_bed_type(m_plater, *request.plate))
329	        throw std::logic_error("The printer form offered a plate OrcaSlicer does not offer for " + name);
330	
331	    for (const SavedPrinter& saved : saved_printers())
332	        if (saved.name == name)
333	            added = saved;
334	    return {};
335	}
