337	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
338	                                               std::vector<std::string>& discarded)
339	{
340	    std::vector<SavedPrinter> printers = saved_printers();
341	    const auto                found    = std::find_if(printers.begin(), printers.end(),
342	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
343	    if (found == printers.end())
344	        return "This app no longer has a printer called \"" + request.name + "\".";
345	
346	    if (request.nozzle) {
347	        const PrinterCandidate* variant = nullptr;
348	        for (const PrinterCandidate& candidate : m_catalog.candidates())
349	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
350	                variant = &candidate;
351	        if (variant == nullptr)
352	            return found->model.empty() ? std::string("The app has no preset of this printer with that nozzle size.") :
353	                                          "The app has no " + found->model + " preset with that nozzle size.";
354	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name, discarded);
355	        if (!problem.empty())
356	            return problem.ToStdString();
357	    }
358	
359	    for (const SavedPrinter& saved : saved_printers())
360	        if (saved.name == request.name)
361	            changed = saved;
362	    return {};
363	}
