370	ManualPrinterResult OrcaPrinterBackend::run_manual_setup()
371	{
372	    // OrcaSlicer's own printer wizard, unchanged, and the printers it
373	    // installs are saved under their own names the way the old dialog's
374	    // manual path did.
375	    const Printers::VendorMap before = wxGetApp().app_config->vendors();
376	    // False when the person closed the wizard without applying it.
377	    if (!wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS))
378	        return {};
379	    const auto names = Printers::name_installed_printers(m_plater, before);
380	    ManualPrinterResult result;
381	    result.applied = true;
382	    for (const SavedPrinter& saved : saved_printers())
383	        if (std::find(names.begin(), names.end(), saved.name) != names.end())
384	            result.added.push_back(saved);
385	    return result;
386	}
