388	void OrcaPrinterBackend::prepare_connection(const std::string& name)
389	{
390	    const CatalogPrinter* model = model_of(name);
391	    if (model == nullptr || model->vendor_id != "BBL")
392	        return;
393	    NetworkAgent* agent = wxGetApp().getAgent();
394	    const std::string fake = fake_bambu_printer_agent_id(wxGetApp().app_config);
395	    if (agent == nullptr || (fake.empty() && !NetworkAgent::is_network_module_loaded()))
396	        return;
397	    const std::string wanted = fake.empty() ? BBL_PRINTER_AGENT_ID : fake;
398	    if (!agent->get_printer_agent() || agent->get_printer_agent()->get_agent_info().id != wanted) {
399	        // A connection gesture selects the networking provider, not a slicing
400	        // preset. NetworkAgent owns callback transfer and disconnects the old
401	        // provider; the open project's settings and unsaved edits stay intact.
402	        // Orca's profile-driven policy takes the provider back the next time
403	        // the printer profile changes; connecting again reinstalls it.
404	        auto provider = NetworkAgentFactory::create_printer_agent_by_id(
405	            wanted, agent->get_cloud_agent(BBL_CLOUD_PROVIDER), Slic3r::data_dir());
406	        if (!provider)
407	            throw std::runtime_error("The registered Bambu printer agent could not be created");
408	        agent->set_printer_agent(std::move(provider));
409	        wxGetApp().sidebar().update_all_preset_comboboxes();
410	    }
411	    agent->start_discovery(true, false);
412	}
