414	DiscoveryPort OrcaPrinterBackend::discovery_port()
415	{
416	    // The fake printer has no socket; on Windows this is not implemented, and
417	    // whether a held port hides printers there has not been tested. "Ours" makes
418	    // no claim: the search reports as if nothing were in the way.
419	#ifdef _WIN32
420	    return DiscoveryPort::Ours;
421	#else
422	    if (!fake_bambu_printer_agent_id(wxGetApp().app_config).empty())
423	        return DiscoveryPort::Ours;
424	    constexpr int port = 2021;
425	    // The plug-in's socket lives in this process and has no API to ask about.
426	    for (int fd = 0; fd < std::min(getdtablesize(), 4096); ++fd) {
427	        sockaddr_in address{};
428	        socklen_t   size = sizeof(address);
429	        int         type = 0;
430	        socklen_t   type_size = sizeof(type);
431	        if (getsockname(fd, reinterpret_cast<sockaddr*>(&address), &size) == 0 && address.sin_family == AF_INET &&
432	            ntohs(address.sin_port) == port && getsockopt(fd, SOL_SOCKET, SO_TYPE, &type, &type_size) == 0 && type == SOCK_DGRAM)
433	            return DiscoveryPort::Ours;
434	    }
435	    const int probe = ::socket(AF_INET, SOCK_DGRAM, 0);
436	    if (probe < 0)
437	        return DiscoveryPort::Ours;
438	    sockaddr_in address{};
439	    address.sin_family      = AF_INET;
440	    address.sin_addr.s_addr = htonl(INADDR_ANY);
441	    address.sin_port        = htons(port);
442	    const bool bound        = ::bind(probe, reinterpret_cast<sockaddr*>(&address), sizeof(address)) == 0;
443	    const int  why          = errno;
444	    ::close(probe);
445	    return bound ? DiscoveryPort::Free : why == EADDRINUSE ? DiscoveryPort::Taken : DiscoveryPort::Ours;
446	#endif
447	}
