461	PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
462	{
463	    PrinterConnectionInfo info;
464	    const auto saved = saved_printers();
465	    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
466	    if (printer == saved.end()) {
467	        info.state = "unavailable";
468	        info.message = "This printer was renamed or removed. Open it again from Printers.";
469	        return info;
470	    }
471	    const CatalogPrinter* model = model_of(name);
472	    if (!model || model->vendor_id != "BBL") {
473	        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
474	        if (!preset)
475	            throw std::logic_error("A saved printer has no preset");
476	        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
477	            settle(*m_host_attempt);
478	        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
479	        info.address = preset->config.opt_string("print_host");
480	        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
481	        info.provider = "host";
482	        info.state = info.address.empty() ? "not_configured" : "unknown";
483	        if (info.state == "unknown")
484	            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
485	        if (info.host_type == "other") {
486	            info.state = "unavailable";
487	            info.message = "Configure this connection type in Printer settings. You can still prepare prints and export a file.";
488	        }
489	        if (m_host_attempt && m_host_attempt->name == name) {
490	            auto& attempt = *m_host_attempt;
491	            // Only a verified attempt saved its settings; it holds while the
492	            // printer is still set up as it was tested.
493	            if (attempt.state == "verified" &&
494	                (info.address != attempt.address || info.host_type != attempt.host_type ||
495	                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
496	                info.message = "Connection settings changed. Test the new connection again.";
497	                return info;
498	            }
499	            info.state = attempt.state;
500	            info.message = attempt.message;
501	        }
502	        return info;
503	    }
504	    info.provider = "bambu";
505	    info.device_id = printer->device_id;
506	    auto* devices = wxGetApp().getDeviceManager();
507	    auto* agent = wxGetApp().getAgent();
508	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
509	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
510	        info.state = "unavailable";
511	        info.needs_network_plugin = true;
512	        const auto load_error = NetworkAgent::get_load_error();
513	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not loaded" +
514	                       (load_error.has_error ? ": " + load_error.message : std::string()) +
515	                       ". The person can already prepare prints for this printer without it.";
516	        return info;
517	    }
518	    if (!devices || !agent) {
519	        info.state = "unavailable";
520	        info.message = "Connecting is not available right now. The person can already prepare prints for this printer.";
521	        return info;
522	    }
523	    // The local list is what has announced itself on this network; the cloud
524	    // list is the person's account, wherever those printers are.
525	    auto nearby = devices->get_local_machinelist();
526	    // For the harness's no-printer chat (JUSPRIN_TEST_HEAR_NOTHING): no printer
527	    // is heard, whatever the real printer announces.
528	    if (std::getenv("JUSPRIN_TEST_HEAR_NOTHING") != nullptr)
529	        nearby.clear();
530	    auto candidates = nearby;
531	    for (const auto& entry : devices->get_my_cloud_machine_list())
532	        candidates[entry.first] = entry.second;
533	    // Every printer the app knows of is listed. One it does not offer carries
534	    // the reason, so the model is never told "found no printer" about a
535	    // printer the app chose not to offer (the P1S case of 2026-10-31, and the
536	    // sweep after it).
537	    for (const auto& [id, machine] : candidates) {
538	        if (!machine)
539	            continue;
540	        ConnectionCandidate candidate{id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer(),
541	                                      nearby.find(id) == nearby.end()};
542	        const auto linked_to = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
543	            return p.name != name && p.device_id == id;
544	        });
545	        if (machine->printer_type != model->device_model_id) {
546	            candidate.reason = "other_model";
547	            candidate.detail = machine->get_printer_type_display_str().ToUTF8().data();
548	        } else if (!info.device_id.empty() && id != info.device_id) {
549	            candidate.reason = "other_device";
550	            candidate.detail = info.device_id;
551	        } else if (linked_to != saved.end()) {
552	            candidate.reason = "linked_elsewhere";
553	            candidate.detail = linked_to->name;
554	        } else if (machine->is_lan_mode_printer() && !machine->is_avaliable()) {
555	            candidate.reason = "occupied";
556	        }
557	        info.candidates.push_back(std::move(candidate));
558	    }
559	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
560	    // is_connected() alone is optimistic immediately after reset(). Require
561	    // actual parsed push data, and fresh LAN data for a LAN connection.
562	    const bool communicating = machine && has_recent_printer_data(*machine);
563	    const bool configured = has_verified_printer_connection(info.device_id);
564	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
565	    if (info.state == "unknown")
566	        info.message = "The app has no recent data from this printer.";
567	    if (m_connection_attempt && m_connection_attempt->name == name) {
568	        const auto& attempt = *m_connection_attempt;
569	        if (info.device_id != attempt.device_id)
570	            throw std::logic_error("A connection attempt lost its saved printer association");
571	        const bool observed = communicating &&
572	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
573	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
574	        // What the plug-in answered to this attempt comes first: upstream's
575	        // handler clears the selection and erases a wrong access code on a
576	        // failure, and reading that state alone named the wrong cause.
577	        const auto answered = Printers::last_connection_event(attempt.device_id);
578	        if (answered && !attempt.reselecting && answered->at >= attempt.connect_requested &&
579	            answered->kind != Printers::ConnectionEvent::Kind::Ok) {
580	            // The printer answered a wrong code, so its port needs no look.
581	            report_failure(info, connection_failure_text(*answered, attempt.connect_requested), answered->code != "5");
582	        } else if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
583	            info.state = "failed";
584	            info.message = "The selected printer changed. Select this printer again to reconnect.";
585	        } else if (observed) {
586	            info.state = "verified";
587	            m_connection_attempt.reset();
588	        } else if (machine == nullptr) {
589	            info.state = "failed";
590	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
591	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
592	            report_failure(info, "The printer did not respond within " + std::to_string(kConnectionWait.count()) + " seconds.", true);
593	        } else {
594	            info.state = "connecting";
595	            info.message.clear();
596	        }
597	    }
598	    if (info.state == "verified")
599	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
600	    if (communicating) {
601	        const auto* extruders = machine->GetExtderSystem();
602	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
603	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
604	    }
605	    return info;
606	}
