608	// On a thread of its own, as a print host's test is: a printer that does not
609	// answer would hold the app for the whole limit.
610	std::shared_ptr<OrcaPrinterBackend::PortLook> OrcaPrinterBackend::start_port_look(const std::string& address)
611	{
612	    auto look = std::make_shared<PortLook>();
613	    std::thread([look, address] {
614	        look->said = Printers::look_at_port(address, kBambuLanPort, kPortLookLimit);
615	        look->done.store(true);
616	    }).detach();
617	    return look;
618	}
