620	void OrcaPrinterBackend::report_failure(PrinterConnectionInfo& info, const std::string& failure, bool look)
621	{
622	    auto& attempt = *m_connection_attempt;
623	    if (!look || attempt.address.empty()) {
624	        info.state   = "failed";
625	        info.message = failure;
626	        return;
627	    }
628	    // The attempt keeps reading "connecting" until both looks are back, so its
629	    // note says everything at once.
630	    if (!attempt.port_after)
631	        attempt.port_after = start_port_look(attempt.address);
632	    if (!attempt.port_before->done.load() || !attempt.port_after->done.load()) {
633	        info.state = "connecting";
634	        info.message.clear();
635	        return;
636	    }
637	    info.state   = "failed";
638	    info.message = failure + " The app also tried the printer's port " + std::to_string(kBambuLanPort) + " at " + attempt.address +
639	                   ". Just before the attempt, " + attempt.port_before->said + ". Right after it failed, " + attempt.port_after->said + ".";
640	}
