642	std::string OrcaPrinterBackend::keep_connection_report(const std::string& text)
643	{
644	    const std::filesystem::path folder = std::filesystem::u8path(Slic3r::data_dir()) / "jusprin" / "connection_reports";
645	    std::error_code             failed;
646	    std::filesystem::create_directories(folder, failed);
647	    const auto seconds = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
648	    const std::filesystem::path path = folder / ("report-" + std::to_string(seconds) + ".json");
649	    std::ofstream               file(path, std::ios::binary);
650	    file << text;
651	    file.close();
652	    return file.good() ? path.u8string() : std::string();
653	}
