655	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
656	                                               const std::string& access_code)
657	{
658	    // The same printer asked for again keeps waiting; anything else replaces
659	    // the attempt below. One that has failed and is only having its port looked
660	    // at is over, though it still reads "connecting".
661	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
662	        connection(name).state == "connecting" && !m_connection_attempt->port_after)
663	        return {};
664	    const auto info = connection(name);
665	    if (info.provider != "bambu" || info.state == "unavailable")
666	        return info.message;
667	    const auto chosen = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; });
668	    if (chosen == info.candidates.end())
669	        return "That printer is not on the list for this connection. Choose one from the list.";
670	    if (!chosen->reason.empty())
671	        return "That printer cannot be chosen (" + chosen->reason + "). Choose another from the list.";
672	    auto* devices = wxGetApp().getDeviceManager();
673	    MachineObject* machine = devices->get_my_machine(device_id);
674	    if (!machine)
675	        machine = devices->get_local_machine(device_id);
676	    if (!machine)
677	        return "That printer is no longer available. Refresh the list and try again.";
678	    if (machine->is_lan_mode_printer()) {
679	        if (access_code.empty() && !machine->has_access_right())
680	            return "Enter the access code shown on your printer.";
681	        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
682	                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
683	            }))
684	            return "The access code can only contain letters and numbers.";
685	    }
686	    const wxString problem = Printers::link_named_printer(name, device_id);
687	    if (!problem.empty())
688	        return problem.ToStdString();
689	    prepare_connection(name);
690	    if (machine->is_lan_mode_printer() && !access_code.empty())
691	        machine->set_user_access_code(access_code);
692	    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
693	                                              std::chrono::system_clock::now(), std::chrono::steady_clock::now()};
694	    if (machine->is_lan_mode_printer() && !machine->get_dev_ip().empty()) {
695	        m_connection_attempt->address     = machine->get_dev_ip();
696	        m_connection_attempt->port_before = start_port_look(m_connection_attempt->address);
697	    }
698	    if (devices->get_selected_machine() != machine) {
699	        devices->set_selected_machine(device_id);
700	        return {};
701	    }
702	    // Selecting the selected LAN printer again disconnects and reconnects
703	    // it, and GUI_App's local-connect handler hears the disconnect one event
704	    // turn later and clears the selection -- after the reconnect. Deselect
705	    // now, and select it again once that notice has run.
706	    m_connection_attempt->reselecting = true;
707	    devices->set_selected_machine("");
708	    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
709	        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
710	            return;
711	        m_connection_attempt->reselecting       = false;
712	        m_connection_attempt->connect_requested = std::chrono::steady_clock::now();
713	        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
714	    });
715	    return {};
716	}
