718	std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
719	                                            const std::string& address, const std::string& api_key)
720	{
721	    const auto info = connection(name);
722	    if (info.provider != "host" || info.state == "unavailable")
723	        return info.message;
724	    if (host_type != "moonraker" && host_type != "octoprint")
725	        return "Choose Moonraker or OctoPrint.";
726	    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
727	        return "Enter the printer's host name, IP address or HTTP URL without credentials.";
728	    if (address.find("://") != std::string::npos && address.rfind("http://", 0) != 0 && address.rfind("https://", 0) != 0)
729	        return "Use an HTTP or HTTPS address.";
730	    const auto* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
731	    if (!preset)
732	        return "This printer was renamed or removed.";
733	    // Reuse a saved secret only for the same endpoint and provider.
734	    const std::string key = api_key.empty() && address == info.address && host_type == info.host_type ?
735	        preset->config.opt_string("printhost_apikey") : api_key;
736	    // Tested on a copy: the printer's own settings change only once the host
737	    // has answered (settle).
738	    DynamicPrintConfig config = preset->config;
739	    config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(host_type == "moonraker" ? htMoonraker : htOctoPrint));
740	    config.set_key_value("print_host", new ConfigOptionString(address));
741	    config.set_key_value("printhost_apikey", new ConfigOptionString(key));
742	    std::unique_ptr<PrintHost> host(PrintHost::get_print_host(&config));
743	    if (!host)
744	        throw std::logic_error("A supported print host has no adapter");
745	    // PrintHost::test blocks until the host answers, and a host that accepts
746	    // the connection and never replies holds it with no upper bound (Http's
747	    // DEFAULT_TIMEOUT_MAX is 0). So it runs on a thread of its own, as
748	    // upstream's upload queue runs these adapters. Nothing waits for it:
749	    // joining could hold the panel's close for as long as the host dawdles,
750	    // and kConnectionWait reports the failure meanwhile. The adapter keeps
751	    // copies of what it read from `config`.
752	    auto verdict = std::make_shared<std::atomic<HostVerdict>>(HostVerdict::Testing);
753	    auto detail  = std::make_shared<std::string>();
754	    std::thread([host = std::move(host), verdict, detail] {
755	        wxString said;
756	        const bool passed = host->test(said);
757	        // Written before the verdict, which the reader loads first.
758	        *detail = said.ToUTF8().data();
759	        verdict->store(passed ? HostVerdict::Passed : HostVerdict::Failed);
760	    }).detach();
761	    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), std::move(detail),
762	                                 "connecting", {}};
763	    return {};
764	}
765	
766	void OrcaPrinterBackend::settle(HostAttempt& attempt)
767	{
768	    switch (attempt.verdict->load()) {
769	    case HostVerdict::Passed: {
770	        const wxString problem = Printers::configure_named_printer_host(
771	            attempt.name, attempt.host_type == "moonraker" ? htMoonraker : htOctoPrint, attempt.address, attempt.api_key);
772	        attempt.state   = problem.empty() ? "verified" : "failed";
773	        attempt.message = problem.ToStdString();
774	        // The test's answer is Home's first word on this host.
775	        if (problem.empty())
776	            Printers::note_host_answered(attempt.name);
777	        break;
778	    }
779	    case HostVerdict::Failed: {
780	        // The host's own answer travels with the failure: "HTTP 401" is the
781	        // key refused, "doesn't look like Moonraker" is another kind of
782	        // host, and curl's reason is the host not reached. One sentence for
783	        // all three sent people to check the network when the host had
784	        // answered.
785	        attempt.state          = "failed";
786	        const std::string said = one_line(*attempt.detail);
787	        attempt.message        = said.empty() ? "The print host test failed, and it gave no reason." :
788	                                                "The print host test failed: " + said;
789	        break;
790	    }
791	    case HostVerdict::Testing:
792	        if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
793	            attempt.state   = "failed";
794	            // What the app saw, without a cause: a name this computer cannot
795	            // look up waits here as long as a host that never answers.
796	            attempt.message = "The print host test had no answer from " + attempt.address + " after " +
797	                              std::to_string(kConnectionWait.count()) + " seconds.";
798	        }
799	        break;
800	    }
801	}
