351	void PrinterConversation::install_network_plugin()
352	{
353	    if (!m_needs_plugin || m_printer_name.empty())
354	        return;
355	    m_backend.install_network_plugin();
356	    // Closing the installer, or a download that failed, leaves the notice
357	    // and its button as they were; Orca's dialog has said what happened.
358	    if (m_backend.connection(m_printer_name).needs_network_plugin)
359	        return;
360	    m_needs_plugin = false;
361	    for (json& block : m_blocks)
362	        if (block.value("kind", std::string()) == "plugin")
363	            block["installed"] = true;
364	    // Discovery could not start without the plug-in; the next status check
365	    // starts it.
366	    m_prepared.clear();
367	    m_search.reset();
368	    m_host.post_note("Bambu's network plug-in is installed now, so " + m_printer_name + " can be connected.");
369	    m_host.session_changed();
370	    m_host.start_turn();
371	}
