405	{
406	    json context = json::object();
407	    if (m_mode == ConversationMode::Add) {
408	        json printers = json::array();
409	        for (const CatalogPrinter& printer : m_backend.catalog())
410	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
