460	json connection_chat_record(const std::vector<Agent::ConversationMessage>& messages, const std::vector<ToolActivity>& activities)
461	{
462	    json turns = json::array();
463	    for (const Agent::ConversationMessage& message : messages)
464	        if (!message.text.empty()) // a turn that only called a tool
465	            turns.push_back({{"role", message.role == Agent::MessageRole::User ? "person" :
466	                                      message.role == Agent::MessageRole::Note ? "app" :
467	                                                                                 "model"},
468	                             {"text", message.text}});
469	    json tools = json::array();
470	    for (const ToolActivity& activity : activities) {
471	        if (activity.tool != "printer_connect" && activity.tool != "printer_connection_status")
472	            continue;
473	        tools.push_back({{"tool", activity.tool},
474	                         {"arguments", json::parse(activity.arguments_json, nullptr, false)},
475	                         {"output", activity.error ? json(activity.error->code + ": " + activity.error->message) :
476	                                                     json::parse(activity.result_json, nullptr, false)}});
477	    }
478	    return json{{"turns", std::move(turns)}, {"tools", std::move(tools)}};
479	}
