495	
496	std::optional<ToolError> PrinterConversation::preflight_tool(ToolHandler handler, ToolActivity& activity)
497	{
498	    // Every session is offered every printer tool, so the tool list stays the
499	    // same for the prompt cache; what a call may do depends on the session.
500	    // Finding and adding a printer belongs to an Add session: a Change or
501	    // Connect session is about a printer the person already has, and an add
502	    // there would save another printer and move the session onto it.
503	    if (m_mode != ConversationMode::Add && (handler == ToolHandler::PrinterIdentify || handler == ToolHandler::PrinterAdd))
504	        return ToolError{"not_in_this_conversation",
505	                         "This conversation is about " + m_printer_name + ", which is already set up; printers are not "
506	                         "found or added here. Tell the person that another printer is added with + Add printer on Home."};
507	    // The settings tools reach the project too; here they reach this
508	    // printer's own settings, and nothing else.
509	    if (handler == ToolHandler::SettingsSearch || handler == ToolHandler::SettingsGet ||
510	        handler == ToolHandler::SettingsPreviewPatch || handler == ToolHandler::SettingsApplyPatch) {
511	        if (m_printer_name.empty())
512	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
513	        const json arguments = json::parse(activity.arguments_json);
514	        if (arguments.value("scope", std::string()) != "printer")
515	            return ToolError{"not_in_this_conversation", "Only this printer's settings are changed here: pass scope printer and "
516	                                                         "target.preset \"" + m_printer_name + "\"."};
517	        if (arguments.at("target").value("preset", std::string()) != m_printer_name)
518	            return ToolError{"other_printer", "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
519	                                              "changed from Printer settings… in its menu on Home."};
520	        return std::nullopt;
521	    }
522	    // A stock profile holds nothing of the person's own: a nozzle size or a
523	    // connection is saved on a printer they have added.
524	    if (about().stock && (handler == ToolHandler::PrinterChange || handler == ToolHandler::PrinterConnect ||
525	                          handler == ToolHandler::PrinterConnectionStatus))
526	        return ToolError{"stock_profile", "\"" + m_printer_name + "\" is the settings JusPrin comes with for this model, not a "
527	                                          "printer the person has added, so its nozzle and connection are not saved. Its other "
528	                                          "settings are changed by saving a copy, which is then theirs (settings_apply_patch with "
529	                                          "persistAs). To keep a nozzle or a connection, they add the printer with + Add printer "
530	                                          "on Home."};
531	    // A change is to the printer this session is about, and only once there
532	    // is one. The model sometimes names a printer on the network instead.
533	    if (handler == ToolHandler::PrinterChange) {
534	        if (saved(m_printer_name).name.empty())
535	            return ToolError{"no_printer", "No printer is set up in this conversation yet: add one first."};
536	        const std::string name = json::parse(activity.arguments_json).value("printerName", std::string());
537	        if (name != m_printer_name)
538	            return ToolError{saved(name).name.empty() ? "unknown_printer" : "other_printer",
539	                             "This conversation can change only \"" + m_printer_name + "\". Another saved printer is "
540	                             "changed from Printer settings… in its menu on Home."};
541	        return std::nullopt;
542	    }
543	    if (handler != ToolHandler::PrinterConnect)
544	        return std::nullopt;
545	    json              arguments = json::parse(activity.arguments_json);
546	    const std::string name      = m_printer_name;
547	    if (saved(name).name.empty())
548	        return ToolError{"no_printer", "There is no saved printer for this conversation: add one first."};
549	    m_connect_tried = true;
550	
551	    const PrinterConnectionInfo info = m_backend.connection(name);
552	    // No printer can be listed without the plug-in, so the reason is that,
553	    // not an unknown device.
554	    if (info.needs_network_plugin)
555	        return ToolError{"connection_unavailable", info.message};
556	    if (info.provider == "bambu") {
557	        // The person names the printer as its list shows it, so its name
558	        // finds it as surely as its id.
559	        const std::string device = arguments.value("deviceId", std::string());
560	        const auto found = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& candidate) {
561	            return offered(candidate) && (candidate.id == device || candidate.name == device);
562	        });
563	        // A call written for a print host reaches this branch with an address
564	        // instead of an id, and may be naming a printer the app has seen.
565	        if (found == info.candidates.end())
566	            return ToolError{"unknown_device", unknown_device_text(info, device.empty() ? arguments.value("address", std::string()) : device)};
567	        activity.title = "Connect to " + found->name;
568	        arguments["deviceId"] = found->id;
569	        arguments["target"]   = found->name;
570	    } else if (info.provider == "host") {
571	        // The registry has already refused a hostType without an address; a
572	        // deviceId here names a Bambu Lab printer this one is not.
573	        if (!arguments.contains("hostType"))
574	            return ToolError{"address_needed", "Pass hostType and the address the person gave."};
575	        m_host_type = arguments["hostType"].get<std::string>();
576	        activity.title      = "Connect to " + arguments["address"].get<std::string>();
577	        arguments["target"] = arguments["address"];
578	    } else
579	        return ToolError{"connection_unavailable", info.message};
580	    // Which field the local form asks for, and the printer it named.
581	    arguments["provider"]    = info.provider;
582	    arguments["printerName"] = name;
583	    activity.arguments_json = arguments.dump();
584	    return std::nullopt;
585	}
586	
587	std::string PrinterConversation::unknown_device_text(const PrinterConnectionInfo& info, const std::string& asked) const
588	{
589	    // What it was asked for may be a printer the app has seen and does not
590	    // offer. An empty id or address is not a match for one with none known.
591	    const auto wanted = std::find_if(info.candidates.begin(), info.candidates.end(), [&asked](const ConnectionCandidate& candidate) {
592	        return !offered(candidate) && !asked.empty() && (candidate.id == asked || candidate.name == asked || candidate.address == asked);
593	    });
594	    if (wanted != info.candidates.end())
595	        return not_offered_text(*wanted) + " It cannot be connected as it is." +
596	               (in_cloud_mode(*wanted) ? std::string(" ") + kPersonsChoice : std::string());
597	
598	    std::string listed;
599	    std::string others;
600	    bool        cloud = false;
601	    for (const ConnectionCandidate& candidate : info.candidates)
602	        if (offered(candidate))
603	            listed += (listed.empty() ? "" : ", ") + candidate.id + " (" + candidate.name + ")";
604	        else {
605	            others += " " + not_offered_text(candidate);
606	            cloud = cloud || in_cloud_mode(candidate);
607	        }
608	    return (listed.empty() ? search_text() : "Pass the deviceId of one of these printers in LAN mode: " + listed + ".") + others +
609	           (cloud ? std::string(" ") + kPersonsChoice : std::string());
610	}
611	
612	std::string PrinterConversation::search_text() const
613	{
614	    if (!m_search)
615	        return "No network search has run yet in this conversation; printer_connection_status starts it.";
616	    const std::string seconds =
617	        std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_search->started).count());
618	    if (m_search->port != DiscoveryPort::Ours)
619	        return m_search->port == DiscoveryPort::Taken ? kPortTaken : kNotListening;
620	    if (!m_search->said_none && !m_search->found)
621	        return "The network search started " + seconds + " seconds ago and has found no printer of this model yet. The app posts a note "
622	               "when one appears, or after about " + std::to_string(kSearchWait.count()) + " seconds with none.";
623	    return "The network search has listened for " + seconds + " seconds and has found no printer of this model in LAN mode." +
624	           (m_search->found ? "" : " The app posts a note if one appears.");
625	}
626	
627	json PrinterConversation::search_json(const PrinterConnectionInfo& info) const
628	{
629	    if (info.provider != "bambu")
630	        return json{{"state", "not_applicable"}};
631	    if (!m_search || info.state == "unavailable")
632	        return json{{"state", "not_started"}};
633	    return json{{"state", m_search->port == DiscoveryPort::Taken ? "port_taken" :
634	                          m_search->port == DiscoveryPort::Free  ? "not_listening" :
635	                          m_search->said_none || m_search->found ? "listening" :
636	                                                                   "started"},
637	                {"secondsAgo", std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_search->started).count()}};
638	}
