640	Result PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
641	{
642	    const json arguments = json::parse(activity.arguments_json);
643	    switch (handler) {
644	    case ToolHandler::PrinterIdentify: return identify(arguments, activity.correlation_id);
645	    case ToolHandler::PrinterAdd: return add(arguments, activity.correlation_id);
646	    case ToolHandler::PrinterChange: return change(arguments);
647	    case ToolHandler::PrinterConnectionStatus: return connection_status(m_printer_name, activity.correlation_id);
648	    case ToolHandler::PrinterConnect: return request_credential(arguments, activity.action_id);
649	    case ToolHandler::IssueReportOpen: return open_issue(arguments);
650	    default: return {};
651	    }
652	}
