666	void PrinterConversation::tool_settled(const ToolActivity& activity)
667	{
668	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
669	        return;
670	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
671	    if (saved_as.empty() || saved_as == m_printer_name)
672	        return;
673	    // Saved as a copy, which Orca selected in the preset's place: the
674	    // printer the person now has, and Home lists it.
