679	
680	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
681	{
682	    std::vector<const CatalogPrinter*> printers;
683	    for (const json& id : arguments.at("catalogIds")) {
684	        const CatalogPrinter* printer = catalog_entry(id);
685	        if (printer == nullptr)
686	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
687	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
688	            printers.push_back(printer);
689	    }
690	    if (printers.size() > kMaximumCandidates)
691	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
692	    const bool stated = said_nozzle(arguments);
693	    for (const CatalogPrinter* printer : printers)
694	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
695	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
696	
697	    json cards = json::array();
698	    json found = json::array();
699	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
700	    for (const CatalogPrinter* printer : printers) {
701	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
702	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
703	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
704	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
705	        found.push_back(json{{"catalogId", printer->id},
706	                             {"brand", printer->vendor_name},
707	                             {"model", printer->model_name},
708	                             {"buildVolume", printer->build_volume},
709	                             {"nozzles", printer->nozzles},
710	                             {"assumed", json{{"nozzle", nozzle},
711	                                              {"plate", nullable(printer->default_plate)},
712	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
713	                             {"alreadyYours", yours}});
714	    }
715	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
716	                            {"kind", "printers"}, {"printers", std::move(cards)}});
717	    m_host.session_changed();
718	    return ok(json{{"printers", std::move(found)}});
719	}
720	
721	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
722	{
723	    const std::string     id      = arguments.at("catalogId");
724	    const CatalogPrinter* printer = catalog_entry(id);
725	    if (printer == nullptr)
726	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
727	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
728	    if (!ships(printer->nozzles, nozzle))
729	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
730	    // A second yes to the same printer is the same printer, not another one.
731	    if (const auto added = m_added.find(id); added != m_added.end())
732	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
733	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
734	                                           "opening Add printer again.");
735	
736	    // Adding never authenticates: credentials belong to connecting, so a
737	    // failed connection cannot repeat this save.
738	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
739	                              printer->filament_for(nozzle), printer->display_name(), {}};
740	    SavedPrinter      added;
741	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
742	        return refuse("add_failed", problem);
743	    const SavedPrinter now = saved(added.name);
744	    if (now.name.empty())
745	        throw std::logic_error("A successful add did not save a printer");
746	    m_printer_name = now.name;
747	    m_added[id]    = now.name;
748	    // The receipt is the app's, drawn from what was saved: the model's reply
749	    // can word the moment any way, but whether it happened is not its to say.
750	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
751	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
752	    m_host.printers_changed(now.name);
753	    m_host.session_changed();
754	    return ok(json{{"printer", printer_json(now)}});
755	}
756	
757	Result PrinterConversation::change(const json& arguments)
758	{
759	    // preflight_tool has checked that this is the session's own printer.
760	    const std::string  name = arguments.at("printerName");
761	    const SavedPrinter now  = saved(name);
762	    // What is loaded is the printer's to report, not the conversation's to
763	    // record: the nozzle is the one physical change this tool saves.
764	    if (!said_nozzle(arguments))
765	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
766	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
767	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
768	
769	    ChangePrinterRequest request;
770	    request.name = name;
771	    if (arguments["nozzle"].get<double>() != now.nozzle)
772	        request.nozzle = arguments["nozzle"].get<double>();
773	    if (!request.nozzle)
774	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
775	
776	    SavedPrinter             changed;
777	    std::vector<std::string> discarded;
778	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
779	        return refuse("change_failed", problem);
780	    const SavedPrinter after = saved(name);
781	    json               what  = json::array();
782	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
783	    m_host.printers_changed();
784	    m_host.session_changed();
785	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
786	}
787	
788	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
789	{
790	    if (saved(name).name.empty())
791	        return refuse("no_printer", "There is no saved printer for this conversation: add one first.");
792	    m_connect_tried = true;
793	    // For a Bambu Lab printer this starts looking for it on the network, once;
794	    // see m_prepared.
795	    if (m_prepared != name) {
796	        m_backend.prepare_connection(name);
797	        m_prepared = name;
798	        m_search.reset();
799	    }
800	    const PrinterConnectionInfo info = m_backend.connection(name);
801	    // A host already saved says which kind it is; until one is, the first
802	    // connection attempt does.
803	    if (info.provider == "host" && !info.address.empty() && m_host_type.empty())
804	        m_host_type = info.host_type;
805	    if (info.needs_network_plugin)
806	        show_plugin_needed(message_id);
807	    if (!m_search && info.provider == "bambu" && info.state != "unavailable")
808	        m_search = NetworkSearch{std::chrono::steady_clock::now()};
809	    // What this read lists, the model now knows: no note need say it again.
810	    // A printer already reached needs no search to report on, however it is
811	    // reached.
812	    if (m_search && (found_on_network(info) || info.state == "verified"))
813	        m_search->found = true;
814	    return ok(connection_json(info, search_json(info)));
815	}
