817	Result PrinterConversation::request_credential(const json& arguments, const std::string& action_id)
818	{
819	    m_credential_action    = action_id;
820	    m_credential_arguments = arguments;
821	    m_host.session_changed();
822	    return ok(json{{"state", "credential_requested"},
823	                   {"message", "The app is waiting for the person to enter the printer credential locally."}});
824	}
825	
826	void PrinterConversation::connect(const json& arguments, const std::string& credential)
827	{
828	    const std::string name   = arguments.at("printerName");
829	    const std::string target = arguments.at("target");
830	    const std::string problem =
831	        arguments.at("provider") == "bambu" ?
832	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
833	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
834	    if (!problem.empty()) {
835	        connection_failed(m_host.post_note("Connection to " + target + " failed: " + problem));
836	        m_host.session_changed();
837	        m_host.start_turn();
838	        return;
839	    }
840	    m_connecting = name;
841	    m_last_look  = {};
842	    m_host.session_changed();
843	}
