845	void PrinterConversation::connection_failed(const std::string& message_id)
846	{
847	    // The rule is the app's, not the model's: a model that is stuck is the one
848	    // least likely to say so. Only where there is a skill a report can improve.
849	    if (++m_failed_connections != 2 || !connection_skill())
850	        return;
851	    const json report{{"report", "connection"},
852	                      {"trigger", "failed_twice"},
853	                      {"connectionType", m_host_type.empty() ? "bambu" : m_host_type},
854	                      {"model", saved(m_printer_name).model},
855	                      {"chat", without_secrets(m_host.chat_record())}};
856	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
857	                            {"kind", "report"}, {"report", report.dump(2)}});
858	    m_host.post_note("The app is asking the person, on a card of its own, whether to send a report of this chat to the JusPrin "
859	                     "developers. Nothing is sent unless they choose to.");
860	}
