862	void PrinterConversation::answer_report(const std::string& block_id, bool send)
863	{
864	    for (json& block : m_blocks) {
865	        if (block.value("id", std::string()) != block_id || block.value("kind", std::string()) != "report" || block.contains("answer"))
866	            continue;
867	        if (send) {
868	            const std::string kept = m_backend.keep_connection_report(block.at("report").get<std::string>());
869	            block["answer"] = kept.empty() ? "failed" : "kept";
870	            block["path"]   = kept;
871	        } else
872	            block["answer"] = "declined";
873	        m_host.post_note(!send                     ? "The person chose not to send the report." :
874	                         block["answer"] == "kept" ? "The person chose to send the report. Sending is not built yet, so it is saved on "
875	                                                     "this computer and has not reached the developers." :
876	                                                     "The person chose to send the report, and it could not be saved.");
877	        m_host.session_changed();
878	        return;
879	    }
