883	
884	IssueLink issue_link(const std::string& title, const std::string& body, const std::string& footer)
885	{
886	    static const std::string page   = "https://github.com/TheSpaghettiDetective/JusPrin/issues/new";
887	    static const std::string marker = percent_encoded("\n\n(Cut short to fit the link.)");
888	    const std::string        start  = page + "?title=" + percent_encoded(title) + "&body=";
889	    const std::string        end    = percent_encoded(footer);
890	    const std::string        whole  = percent_encoded(body);
891	    if (start.size() + whole.size() + end.size() <= kIssueLinkLimit)
892	        return {start + whole + end, false};
893	    if (start.size() + marker.size() + end.size() > kIssueLinkLimit)
894	        throw std::logic_error("An issue's title and footer leave no room for its body");
895	    // Whole characters, so the cut never splits one.
896	    const std::size_t room = kIssueLinkLimit - start.size() - marker.size() - end.size();
897	    std::string       kept;
898	    for (std::size_t from = 0; from < body.size();) {
899	        std::size_t next = from + 1;
900	        while (next < body.size() && (static_cast<unsigned char>(body[next]) & 0xC0) == 0x80)
901	            ++next;
902	        const std::string character = percent_encoded(body.substr(from, next - from));
903	        if (kept.size() + character.size() > room)
904	            break;
905	        kept += character;
906	        from = next;
907	    }
908	    return {start + kept + marker + end, true};
909	}
