911	Result PrinterConversation::open_issue(const json& arguments)
912	{
913	    // The tool is offered only with the connection skill, and the footer
914	    // below is the Bambu Lab one: another connection type's needs its own.
915	    const std::optional<Agent::SessionSkill> skill = connection_skill();
916	    if (!skill || skill->trigger != Agent::Protocol::SkillTrigger::kConnectBambu)
917	        throw std::logic_error("issue_report_open ran in a printer chat with no connection skill in force");
918	    const SavedPrinter          printer = saved(m_printer_name);
919	    const PrinterConnectionInfo info    = m_backend.connection(m_printer_name);
920	    std::vector<std::string>    known{printer.device_id, info.device_id, info.address};
921	    for (const ConnectionCandidate& candidate : info.candidates) {
922	        known.push_back(candidate.id);
923	        known.push_back(candidate.address);
924	    }
925	    // The app's own facts, which the model may have wrong or left out.
926	    const std::string footer = "\n\n---\nApp version: " + m_host.app_version() + "\nConnection: Bambu Lab, LAN mode\nPrinter: " +
927	                               printer.model;
928	    const IssueLink link = issue_link(for_public(arguments.at("title").get<std::string>(), known),
929	                                    for_public(arguments.at("body").get<std::string>(), known), footer);
930	    if (!m_host.open_in_browser(link.url))
931	        return refuse("failed", "The app could not open the person's browser, so no issue page is open.");
932	    std::string message = "The new issue page is open in the person's browser, filled in. Nothing has been filed: it is filed "
933	                          "only when they press Submit on it, signed in to GitHub.";
934	    if (link.shortened)
935	        message += " The body was too long for the link, so its end was cut; they can add the rest on the page.";
936	    return ok(json{{"state", "opened"}, {"shortened", link.shortened}, {"message", message}});
937	}
