947	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
948	{
949	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
950	        m_form->options = m_form->reading.get();
951	        m_host.session_changed();
952	    }
953	    watch_search(now);
954	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
955	        return;
956	    m_last_look = now;
957	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
958	    if (info.state == "connecting")
959	        return;
960	    const std::string name = m_connecting;
961	    m_connecting.clear();
962	    const std::string note = m_host.post_note(info.state == "verified" ? "Connection to " + name + " verified." :
963	                                                                         "Connection to " + name + " failed: " + info.message);
964	    if (info.state != "verified")
965	        connection_failed(note);
966	    m_host.printers_changed();
967	    m_host.session_changed();
968	    m_host.start_turn();
969	}
970	
971	void PrinterConversation::watch_search(std::chrono::steady_clock::time_point now)
972	{
973	    // An attempt under way is read by tick alone: reading a connection can
974	    // settle it.
975	    if (!m_search || m_search->found || !m_connecting.empty() ||
976	        now - m_search->last_look < (m_search->said_none || m_search->port != DiscoveryPort::Ours ? std::chrono::seconds(kSearchLateLook) :
977	                                                                                                       std::chrono::seconds(kConnectionLook)))
978	        return;
979	    m_search->last_look = now;
980	    const PrinterConnectionInfo info = m_backend.connection(m_prepared);
981	    // The printer was renamed or removed, or nothing can reach the network now.
982	    if (info.provider != "bambu" || info.state == "unavailable") {
983	        m_search.reset();
984	        return;
985	    }
986	    if (info.state == "verified") {
987	        m_search->found = true;
988	        return;
989	    }
990	    std::string note;
991	    if (found_on_network(info)) {
992	        m_search->found = true;
993	        bool cloud = false;
994	        for (const ConnectionCandidate& candidate : info.candidates) {
995	            if (candidate.account_only)
996	                continue;
997	            cloud = cloud || in_cloud_mode(candidate);
998	            if (offered(candidate))
999	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) + " in LAN mode";
1000	            else if (in_cloud_mode(candidate))
1001	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) +
1002	                        " with LAN Only off, which cannot be connected as it is";
1003	            else
1004	                // Heard, and not this printer: said as such, so "found no
1005	                // printer of this model" is never the note about a printer
1006	                // the app saw.
1007	                note += (note.empty() ? "The network search heard a printer it does not offer: " : "; ") + not_offered_text(candidate);
1008	        }
1009	        note += ".";
1010	        if (cloud)
1011	            note += std::string(" ") + kPersonsChoice;
1012	    } else if (now - m_search->started < kSearchWait)
1013	        return;
1014	    else {
1015	        // Checked only once discovery has had time to bind: the check itself
1016	        // binds the port for a moment, which could cost discovery its own bind.
1017	        const DiscoveryPort port = m_backend.discovery_port();
1018	        if (port == m_search->port && (port != DiscoveryPort::Ours || m_search->said_none))
1019	            return;
1020	        m_search->port = port;
1021	        if (port == DiscoveryPort::Taken)
1022	            note = kPortTaken;
1023	        else if (port == DiscoveryPort::Free)
1024	            note = kNotListening;
1025	        else {
1026	            m_search->said_none = true;
1027	            note = "The network search has listened for " + std::to_string(kSearchWait.count()) +
1028	                   " seconds and has found no printer of this model. The app posts another note if one appears.";
1029	        }
1030	    }
1031	    m_host.post_note(note);
1032	    m_host.session_changed();
1033	    m_host.start_turn();
1034	}
