207	// A printer the app offers to connect: in LAN mode, and not held back for a
208	// reason of the backend's.
209	bool offered(const ConnectionCandidate& candidate) { return candidate.lan_mode && candidate.reason.empty(); }
210	
211	// A printer in cloud mode on this network: the one kind the person can
212	// change by turning LAN Only on.
213	bool in_cloud_mode(const ConnectionCandidate& candidate)
214	{
215	    return !candidate.lan_mode && !candidate.account_only && candidate.reason.empty();
216	}
217	
218	// Why a printer is in `seen` rather than offered.
219	std::string seen_reason(const ConnectionCandidate& candidate)
220	{
221	    if (!candidate.reason.empty())
222	        return candidate.reason;
223	    return candidate.account_only ? "account_only" : "cloud_mode";
224	}
225	
226	// A printer the app knows of and does not offer, and what it knows about it.
227	std::string not_offered_text(const ConnectionCandidate& candidate)
228	{
229	    const std::string reason = seen_reason(candidate);
230	    if (reason == "account_only")
231	        return candidate.name + " is on the person's Bambu account and has not been seen on the network.";
232	    if (reason == "cloud_mode")
233	        return with_address(candidate) + " was seen on the network with LAN Only off.";
234	    if (reason == "other_model")
235	        return with_address(candidate) + " is " +
236	               (candidate.detail.empty() ? std::string("a printer of another model") : "a " + candidate.detail) +
237	               ", not this printer's model.";
238	    if (reason == "linked_elsewhere")
239	        return with_address(candidate) + " is already the printer \"" + candidate.detail +
240	               "\" in this app, and a device connects to one saved printer.";
241	    if (reason == "other_device")
242	        return with_address(candidate) + " is a printer of this model, but not the one this printer was "
243	               "set up from (" + candidate.detail + ").";
244	    if (reason == "occupied")
245	        return with_address(candidate) + " is in LAN mode, but its bind state is not free (occupied), so it is not offered.";
246	    throw std::logic_error("A connection candidate has a reason this conversation does not know: " + reason);
247	}
248	
249	// Only LAN mode can be connected. Every other printer the app heard of is
250	// reported apart, with the reason, so the model knows it was seen and is
251	// never told "found no printer" about one the app chose not to offer.
252	json connection_json(const PrinterConnectionInfo& info, json search)
253	{
254	    json candidates = json::array();
255	    json seen       = json::array();
256	    for (const ConnectionCandidate& candidate : info.candidates)
257	        if (offered(candidate))
258	            candidates.push_back(json{{"deviceId", candidate.id}, {"name", candidate.name}, {"address", candidate.address}});
259	        else {
260	            json entry{{"name", candidate.name}, {"address", candidate.address}, {"reason", seen_reason(candidate)}};
261	            if (!candidate.detail.empty())
262	                entry["detail"] = candidate.detail;
263	            seen.push_back(std::move(entry));
264	        }
265	    return json{{"provider", info.provider},         {"state", info.state},         {"message", info.message},
266	                {"candidates", std::move(candidates)}, {"seen", std::move(seen)},   {"search", std::move(search)},
267	                {"address", info.address},           {"hostType", info.host_type},  {"nozzleMismatch", info.nozzle_mismatch}};
268	}
