286	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
287	{
288	    // An attempt the last session left waiting -- its panel closed meanwhile
289	    // -- is dropped before this session can read, and save, its outcome.
290	    abandon_connection();
291	    m_mode         = mode;
292	    m_printer_name = mode == ConversationMode::Add ? std::string() : printer_name;
293	    m_blocks       = json::array();
294	    m_next_block   = 1;
295	    m_opened       = false;
296	    // A new session's page writes its instructions again.
297	    m_instructions.clear();
298	    m_network.clear();
299	    m_credential_action.clear();
300	    m_credential_arguments = json::object();
301	    m_prepared.clear();
302	    m_search.reset();
303	    m_added.clear();
304	    m_needs_plugin = false;
305	    m_connect_tried = mode == ConversationMode::Connect;
306	    m_host_type.clear();
307	    m_failed_connections = 0;
308	    m_form.reset();
309	
310	    // The session is the one it was opened for. Its opener names a printer
311	    // it has just read -- a saved one, or for a change the stock profile the
312	    // project has selected -- so a name that finds neither is its bug.
313	    if ((m_mode == ConversationMode::Change && about().name.empty()) ||
314	        (m_mode == ConversationMode::Connect && saved(m_printer_name).name.empty()))
315	        throw std::logic_error("A printer conversation was opened for a printer that is not there: " + m_printer_name);
316	
317	    if (m_mode == ConversationMode::Add) {
318	        m_network = m_backend.network_printers();
319	        // A photo is the fastest way in, and the printers already on the
320	        // network are worth naming. Both sit under the opening, where the
321	        // person is deciding what to say.
322	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
323	        if (!m_network.empty()) {
324	            json found = json::array();
325	            for (const DiscoveredPrinter& printer : m_network)
326	                found.push_back(json{{"name", printer.name}, {"serial", printer.stable_id}, {"online", printer.connected}});
327	            m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""},
328	                                    {"kind", "network"}, {"printers", std::move(found)}});
329	        }
330	    }
331	    // Connecting a Bambu Lab printer that nothing can reach yet: the opening
332	    // says so, and the notice under it offers the plug-in.
333	    if (m_mode == ConversationMode::Connect && saved(m_printer_name).vendor_id == "BBL" &&
334	        m_backend.connection(m_printer_name).needs_network_plugin)
335	        show_plugin_needed({});
336	    m_host.session_changed();
337	}
