1038	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
1039	{
1040	    if (type == "printer_instructions") {
1041	        // Bounded: the page's words become every request's system prompt.
1042	        const std::string text = payload.value("text", std::string());
1043	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
1044	            m_instructions = text;
1045	            m_host.profile_changed();
1046	        }
1047	        return true;
1048	    }
1049	    if (type == "printer_opening") {
1050	        // The first line is the page's to write and the app's to post, once:
1051	        // a reloaded page asks again, and the thread already has it.
1052	        const std::string text = payload.value("text", std::string());
1053	        if (m_opened || text.empty() || text.size() > kNoteLimit)
1054	            return true;
1055	        m_opened                     = true;
1056	        const std::string message_id = m_host.post_opening(text);
1057	        for (json& entry : m_blocks)
1058	            if (entry.value("afterMessageId", std::string()).empty())
1059	                entry["afterMessageId"] = message_id;
1060	        m_host.session_changed();
1061	        return true;
1062	    }
1063	    if (type != "printer_action")
1064	        return false;
1065	
1066	    const std::string action = payload.value("action", std::string());
1067	    if (action == "close")
1068	        m_host.close_panel();
1069	    else if (action == "manual_setup")
1070	        open_form();
1071	    else if (action == "form_options")
1072	        ask_form_options(payload);
1073	    else if (action == "form_finish")
1074	        finish_form(payload);
1075	    else if (action == "form_close") {
1076	        m_form.reset();
1077	        m_host.session_changed();
1078	    } else if (action == "orca_printer_list") {
1079	        // OrcaSlicer's own printer list, for a panel whose page could not
1080	        // load and so cannot show the form; what it added is news the model
1081	        // answers.
1082	        const ManualPrinterResult result = m_backend.run_manual_setup();
1083	        if (!result.added.empty()) {
1084	            m_printer_name = result.added.front().name;
1085	            m_host.post_note("The person added " + m_printer_name + " from the printer list.");
1086	            m_host.printers_changed(m_printer_name);
1087	            m_host.session_changed();
1088	            m_host.start_turn();
1089	        }
1090	    } else if (action == "connect" && payload.value("actionId", std::string()) == m_credential_action &&
1091	               payload.contains("credential") && payload["credential"].is_string()) {
1092	        const json arguments = std::move(m_credential_arguments);
1093	        m_credential_action.clear();
1094	        m_credential_arguments = json::object();
1095	        connect(arguments, payload["credential"].get<std::string>());
1096	    } else if (action == "open_printer_settings" && !m_printer_name.empty()) {
1097	        m_backend.open_printer_settings(m_printer_name);
1098	        m_host.printers_changed();
1099	        m_host.session_changed();
1100	    } else if (action == "undo_add")
1101	        undo_add(payload.value("blockId", std::string()));
1102	    else if (action == "install_network_plugin")
1103	        install_network_plugin();
1104	    else if (action == "report_send" || action == "report_decline")
1105	        answer_report(payload.value("blockId", std::string()), action == "report_send");
1106	    return true;
1107	}
