1109	void PrinterConversation::undo_add(const std::string& block_id)
1110	{
1111	    json* receipt = nullptr;
1112	    for (json& block : m_blocks)
1113	        if (block.value("id", std::string()) == block_id && block.value("kind", std::string()) == "added")
1114	            receipt = &block;
1115	    // A second tap that arrived before the page redrew the first has nothing
1116	    // left to undo.
1117	    if (receipt == nullptr || receipt->value("removed", false))
1118	        return;
1119	
1120	    // Orca's own delete, as Home's "Remove printer…" runs it: the printer the
1121	    // project was set up for gives way to the profile it was based on.
1122	    const std::string name = receipt->at("printer").at("name");
1123	    if (const std::string problem = m_backend.remove_printer(name); !problem.empty()) {
1124	        m_host.post_note("Undo did not remove " + name + ": " + problem);
1125	        m_host.session_changed();
1126	        return;
1127	    }
1128	    // printer_add saves a printer based on a shipped profile, which Orca
1129	    // deletes without asking; only a printer of the person's own design can
1130	    // be kept by declining there.
1131	    if (!saved(name).name.empty())
1132	        throw std::logic_error("Removing an added printer left it saved");
1133	
1134	    if (m_connecting == name)
1135	        abandon_connection();
1136	    (*receipt)["removed"] = true;
1137	    // The same printer can now be added again, and nothing here is about it.
1138	    for (auto added = m_added.begin(); added != m_added.end();)
1139	        added = added->second == name ? m_added.erase(added) : std::next(added);
1140	    if (m_printer_name == name)
1141	        m_printer_name.clear();
1142	    if (m_prepared == name) {
1143	        m_prepared.clear();
1144	        m_search.reset();
1145	    }
1146	    m_host.post_note("The person tapped Undo on the receipt: " + name + " is removed and is no longer one of their printers.");
1147	    m_host.printers_changed();
1148	    m_host.session_changed();
1149	    m_host.start_turn();
1150	}
