1154	void PrinterConversation::open_form()
1155	{
1156	    // A printer is added in an Add session only, as printer_add is.
1157	    if (m_mode != ConversationMode::Add)
1158	        return;
1159	    // An earlier form's read is waited for first: the backend's copy of the
1160	    // person's own presets is what that read is using.
1161	    m_form.reset();
1162	    m_backend.prepare_setup_options();
1163	    PrinterForm form;
1164	    // A machine that already has a printer is that printer, and the form
1165	    // adds new ones; a model the catalogue lacks cannot be set up from it.
1166	    const std::vector<SavedPrinter> printers = m_backend.saved_printers();
1167	    for (DiscoveredPrinter& found : m_backend.nearby_printers()) {
1168	        if (std::any_of(printers.begin(), printers.end(),
1169	                        [&found](const SavedPrinter& printer) { return printer.device_id == found.stable_id; }))
1170	            continue;
1171	        const auto& catalog = m_backend.catalog();
1172	        const auto  model   = std::find_if(catalog.begin(), catalog.end(), [&found](const CatalogPrinter& printer) {
1173	            return !printer.device_model_id.empty() && printer.device_model_id == found.device_model_id;
1174	        });
1175	        if (model != catalog.end())
1176	            form.nearby.emplace_back(std::move(found), model->id);
1177	    }
1178	    m_form = std::move(form);
1179	    m_host.session_changed();
1180	}
