1203	void PrinterConversation::finish_form(const json& payload)
1204	{
1205	    if (!m_form)
1206	        return;
1207	    const std::string     id      = payload.value("catalogId", std::string());
1208	    const double          nozzle  = payload.value("nozzle", 0.);
1209	    const CatalogPrinter* printer = catalog_entry(id);
1210	    // The page finishes from the options it was sent; anything else is a
1211	    // page out of step with the app, and nothing is saved from it.
1212	    const auto refuse_form = [this](const std::string& why) {
1213	        m_form->error = why;
1214	        m_host.session_changed();
1215	    };
1216	    const std::optional<SetupOptions>& options = m_form->options;
1217	    if (printer == nullptr || !options || options->catalog_id != id || options->nozzle != nozzle || !options->error.empty())
1218	        return refuse_form(options && !options->error.empty() ? options->error : "The form was out of date. Choose the printer again.");
1219	
1220	    std::optional<int> plate;
1221	    std::string        plate_label;
1222	    if (!options->plates.empty()) {
1223	        const int  type  = payload.value("plate", 0);
1224	        const auto found = std::find_if(options->plates.begin(), options->plates.end(),
1225	                                        [type](const PlateOption& option) { return option.type == type; });
1226	        if (found == options->plates.end())
1227	            return refuse_form("Choose the plate on this printer.");
1228	        plate       = type;
1229	        plate_label = found->label;
1230	    }
1231	
1232	    // The filament to start with: one that fits, which is installed with
1233	    // the printer; one of the person's own; one made for other printers,
1234	    // which is copied for this one; or a preset the person makes in
1235	    // OrcaSlicer's Create filament window once the printer is added.
1236	    const bool        create   = payload.value("create", false);
1237	    const std::string filament = create ? std::string() : payload.value("filament", std::string());
1238	    const auto        in       = [&filament](const std::vector<FilamentOption>& list) -> const FilamentOption* {
1239	        const auto found = std::find_if(list.begin(), list.end(), [&filament](const FilamentOption& option) { return option.name == filament; });
1240	        return found == list.end() ? nullptr : &*found;
1241	    };
1242	    const FilamentOption* fitting = filament.empty() ? nullptr : in(options->filaments);
1243	    const FilamentOption* other   = filament.empty() ? nullptr : in(options->others);
1244	    const FilamentOption* own     = filament.empty() ? nullptr : in(options->own);
1245	    if (!filament.empty() && fitting == nullptr && other == nullptr && own == nullptr)
1246	        return refuse_form("That filament is no longer on the list. Choose another.");
1247	
1248	    const std::string device = payload.value("deviceId", std::string());
1249	    const auto        found  = std::find_if(m_form->nearby.begin(), m_form->nearby.end(),
1250	                                            [&device](const auto& entry) { return entry.first.stable_id == device; });
1251	    if (!device.empty() && (found == m_form->nearby.end() || found->second != id))
1252	        return refuse_form("That printer is no longer on the list. Choose it again.");
1253	
1254	    // The printer is installed with a filament that fits: the chosen one, or
1255	    // the profile's default until the chosen one is in place.
1256	    AddPrinterRequest request{printer->vendor_id, printer->model_id, number_text(nozzle),
1257	                              fitting != nullptr ? fitting->name : options->default_filament, printer->display_name(), device, plate};
1258	    SavedPrinter      added;
1259	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
1260	        return refuse_form(problem);
1261	    const SavedPrinter now = saved(added.name);
1262	    if (now.name.empty())
1263	        throw std::logic_error("A successful add did not save a printer");
1264	
1265	    const auto label_of = [&options](const std::string& name) {
1266	        for (const auto* list : {&options->filaments, &options->others, &options->own})
1267	            for (const FilamentOption& option : *list)
1268	                if (option.name == name)
1269	                    return option.label;
1270	        return name;
1271	    };
1272	    std::string starting = fitting != nullptr ? fitting->label : label_of(options->default_filament);
1273	    std::string filament_note;
1274	    if (own != nullptr || other != nullptr) {
1275	        const FilamentOption& chosen = own != nullptr ? *own : *other;
1276	        const bool            copy   = !chosen.made_for.empty();
1277	        std::string           used;
1278	        if (const std::string problem = m_backend.start_with_filament(now.name, chosen.name, copy, used); !problem.empty())
1279	            filament_note = " " + chosen.label + " could not be used: " + problem + " It starts with " + starting + ".";
1280	        else if (copy)
1281	            starting = "a copy of " + chosen.label + " saved for this printer as " + used;
1282	        else
1283	            starting = "their own preset " + used;
1284	    }
1285	    if (create) {
1286	        const std::string made = m_backend.create_filament_preset(now.name);
1287	        filament_note = made.empty() ? " The person opened the Create filament window and no new preset for this printer is in slot 1, so it starts with " +
1288	                                           starting + "."
1289	                                     : " The person made the filament preset " + made + " in the Create filament window; it is in slot 1.";
1290	    }
1291	
1292	    std::string note = "The person added " + now.name + " themselves with the printer form: " + printer->display_name() + ", " +
1293	                       number_text(nozzle) + " mm nozzle";
1294	    if (!plate_label.empty())
1295	        note += ", " + plate_label;
1296	    if (!create && filament_note.empty() && !starting.empty())
1297	        note += ", starting with " + starting;
1298	    note += "." + filament_note;
1299	    if (!device.empty())
1300	        note += " It is linked to the printer " + found->first.name + ", which is not connected yet.";
1301	
1302	    m_form.reset();
1303	    m_printer_name = now.name;
1304	    m_added[id]    = now.name;
1305	    // Choosing a printer found on the network is trying to reach that one;
1306	    // choosing a model alone is not.
1307	    m_connect_tried = m_connect_tried || !device.empty();
1308	    m_host.post_note(note);
1309	    m_host.printers_changed(now.name);
1310	    m_host.session_changed();
1311	    m_host.start_turn();
1312	}
