// OrcaSlicer's Moonraker test, which reads Klipper's state from /server/info
// and only logs it; this one also hands it back on a pass. Without it the
// printer chat said "verified" while Klipper was shut down, and the model
// told the person they could send prints. The request and every failure are
// upstream's, copied from Moonraker::test: when that changes, change this.
class MoonrakerKeepingState : public Moonraker
{
public:
    using Moonraker::Moonraker;

    bool test(wxString& msg) const override
    {
        bool passed = true;
        auto http   = Http::get(make_url("server/info"));
        set_auth(http);
        http.on_error([&](std::string body, std::string error, unsigned status) {
                passed = false;
                msg    = format_error(body, error, status);
            })
            .on_complete([&](std::string body, unsigned) {
                try {
                    std::stringstream            stream(body);
                    boost::property_tree::ptree  tree;
                    boost::property_tree::read_json(stream, tree);
                    const auto klippy_state = tree.get_optional<std::string>("result.klippy_state");
                    if (!klippy_state) {
                        passed = false;
                        msg    = _L("The host responded but it doesn't look like Moonraker (missing result.klippy_state).");
                        return;
                    }
                    msg = wxString::FromUTF8(*klippy_state);
                } catch (const std::exception& ex) {
                    passed = false;
                    msg    = GUI::format_wxstr(_L("Could not parse Moonraker server response: %s"), ex.what());
                }
            })
#ifdef WIN32
            .ssl_revoke_best_effort(m_ssl_revoke_best_effort)
#endif
            .perform_sync();
        return passed;
    }
};

